const lessonTools = ALL_TOOLS.filter(x =>
  /lesson/i.test(x.name + " " + x.description) ||
  /read_tasks|read_minutes/i.test(x.name + " " + x.description)
);
text(lessonTools);

const [tasksResult, minutesResult] = await Promise.all([
  tools.mcp__lesson__read_tasks({}),
  tools.mcp__lesson__read_minutes({})
]);

function parseTextJson(result, label) {
  if (!result || !Array.isArray(result.content)) {
    throw new Error(`${label}: CallToolResult.content가 없습니다.`);
  }
  const blocks = result.content.filter(b => b && b.type === "text" && typeof b.text === "string");
  if (blocks.length === 0) throw new Error(`${label}: text 블록이 없습니다.`);
  const parsed = [];
  for (const b of blocks) {
    try { parsed.push(JSON.parse(b.text)); }
    catch (e) { throw new Error(`${label}: text 블록 JSON 파싱 실패`); }
  }
  return parsed.length === 1 ? parsed[0] : parsed;
}

const tasks = parseTextJson(tasksResult, "read_tasks");
const minutes = parseTextJson(minutesResult, "read_minutes");
text(JSON.stringify({
  tasks_shape: Array.isArray(tasks) ? "array" : Object.keys(tasks),
  minutes_shape: Array.isArray(minutes) ? "array" : Object.keys(minutes),
  tasks,
  minutes
}, null, 2));

