const tasksResult = await tools.mcp__lesson__read_tasks({});
const minutesResult = await tools.mcp__lesson__read_minutes({});

function parseTextBlocks(result) {
  return result.content
    .filter(b => b?.type === "text")
    .flatMap(b => {
      const v = JSON.parse(b.text);
      return Array.isArray(v) ? v : [v];
    });
}

const tasks = parseTextBlocks(tasksResult);
const minutes = parseTextBlocks(minutesResult);
const taskById = new Map(tasks.map(t => [t.id, t]));
const minutesByTaskId = new Map();
for (const m of minutes) {
  if (!minutesByTaskId.has(m.task_id)) minutesByTaskId.set(m.task_id, []);
  minutesByTaskId.get(m.task_id).push({ meeting: m.meeting, note: m.note });
}
const joined = tasks.map(t => ({
  ...t,
  minutes: minutesByTaskId.get(t.id) ?? []
}));
const ref = "2026-09-13";

const result = {
  reference_date: ref,
  join_rule: "minutes.task_id === tasks.id",
  completed: joined.filter(x => x.status === "done"),
  overdue_in_progress: joined.filter(x =>
    x.status === "in_progress" && typeof x.due === "string" && x.due < ref
  ),
  unassigned: joined.filter(x => x.owner == null),
  no_due_date: joined.filter(x => x.due == null),
  minutes_only: minutes
    .filter(m => !taskById.has(m.task_id))
    .map(m => ({
      task_id: m.task_id,
      meeting: m.meeting,
      note: m.note
    }))
};
text(JSON.stringify(result, null, 2));

